import{_ as i,C as a,c as r,o as s,aa as l,G as n}from"./chunks/framework.Cn7WEiMX.js";const c="/assets/oraxen_folder.cjdfbYhQ.png",p="/assets/oraxen_inv.DV4VHorx.png",y=JSON.parse('{"title":"💎 Oraxen","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/MMOInventory/compatibility/oraxen.md","filePath":"wiki/MMOInventory/compatibility/oraxen.md"}'),d={name:"wiki/MMOInventory/compatibility/oraxen.md"};function h(m,e,_,x,g,k){const t=a("NolebaseGitContributors"),o=a("NolebaseGitChangelog");return s(),r("div",null,[e[0]||(e[0]=l('<h1 id="💎-oraxen" tabindex="-1">💎 Oraxen <a class="header-anchor" href="#💎-oraxen" aria-label="Permalink to &quot;💎 Oraxen&quot;">​</a></h1> <p>本章讲述了 MMOInventory 与 <a href="https://oraxen.com/" target="_blank" rel="noreferrer">Oraxen</a> 之间的内置联动。需要注意的是，这不表示插件不支持其他物品插件，只是表示 Oraxen 有一些额外的联动功能。</p> <h2 id="自定义纹理" tabindex="-1">自定义纹理 <a class="header-anchor" href="#自定义纹理" aria-label="Permalink to &quot;自定义纹理&quot;">​</a></h2> <p>MMOInventory 1.6.5 引入了 Oraxen 支持。因为 MMOInventory 需要用到自定义资源包，它会在启动时检测 Oraxen，并将对应物品注册入条目。你只需要将所有物品纹理放入 <code>Oraxen/pack/textures/items/mmoinventory</code> 文件夹即可。纹理格式必须为 <code>.PNG</code>，且名称也必须全部小写。<code>slots.yml</code> 与 Oraxen 纹理文件夹也必须完全对应！如果存在错误，Oraxen 可能会抛出纹理报错。默认的 MMOInventory <code>slots.yml</code> 配置如下：</p> <figure><img src="'+c+'" alt="" tabindex="0"><figcaption></figcaption></figure> <p>如果你在 <code>Oraxen/items/</code> 中发现了 <code>mmoinventory-hook.yml</code> 文件，切勿擅自修改！它由 MMOInventory 自动生成，负责将注册资源包中的所有物品，处理所有 Oraxen 兼容相关内容。</p> <h2 id="自定义界面纹理" tabindex="-1">自定义界面纹理 <a class="header-anchor" href="#自定义界面纹理" aria-label="Permalink to &quot;自定义界面纹理&quot;">​</a></h2> <p>你还可以利用 Oraxen 的自定义字形功能，给界面添加自定义贴图。你可以用 PAPI 变量 <code>%oraxen_&lt;glyph_id&gt;%</code> 引用贴图。另外也请确保你在使用自定义界面贴图时去掉了 <code>items.yml</code> 中填充物品部分的配置。</p> <figure><img src="'+p+`" alt="" tabindex="0"><figcaption></figcaption></figure> <p>在界面名称里插入 Oraxen 自定义字形非常简单。打开 <code>language.yml</code> 配置文件，作出如下修改即可：</p> <div class="language-YAML vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">YAML</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">inventory-name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    self</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;&amp;f%oraxen_shift_16%%oraxen_shift_2%%oraxen_mmoinv_default%&#39;</span></span></code></pre></div><p>如果你从未接触过自定义标签/界面贴图/图标，且对上面展示图的效果感到惊奇，就去试着深入了解它吧。Oraxen 基本上能自动处理自定义物品/界面/表情的贴图。</p> `,23)),n(t),n(o)])}const u=i(d,[["render",h]]);export{y as __pageData,u as default};
